function finishCelebration(summary,stars){const car=RALLY_CARS.find(c=>c.id===race.car)||RALLY_CARS[0],world=worldFor(race.world);return `<div class="rally-finish-banner ${summary.finished?'celebrate':''}">${summary.finished?Array.from({length:24},(_,i)=>`<i class="rally-confetti" style="--x:${(i*43)%100}%;--delay:${(i%6)*.17}s;--spin:${i%2?1:-1};--confetti:${['#b0f438','#62d6ff','#ffd254','#ff7391'][i%4]}"></i>`).join(''):''}<div class="rally-finish-icon">${summary.finished?summary.position===1?'🏆':'🏁':'🔧'}</div><div><span class="rally-kicker">${esc(world.name)} · ${esc(car.name)}</span><h2>${summary.finished?summary.position===1?'You own the finish line!':'Another course conquered.':'Back to the learning pit stop.'}</h2>${race.quick?'':`<div class="rally-earned-stars" aria-label="${stars} of 3 stars">${[0,1,2].map(i=>`<span class="${i<stars?'earned':''}" style="animation-delay:${i*.2}s">★</span>`).join('')}</div>`}<p>${race.quick?'Quick practice is saved in your race history. Switch to Circuit Cup to earn stars.':summary.finished?'Stars earned through your racing and maths accuracy.':'Review your missed questions and come back stronger.'}</p></div></div>`}
function showResults(){if(classRace){finishAssignedRace();return}stage='results';cancelAnimationFrame(raf);const summary=summariseRace(race,questions),progress={};if(!race.quick&&allStageAnswersComplete()&&summary.finished)progress[progressKey(lastConfig)]=[race.stageTrackId];const stars=!race.quick&&allStageAnswersComplete()?raceStars(summary):0,courseIndex=RALLY_TRACKS.findIndex(track=>track.id===race.stageTrackId),course=getTrack(race.stageTrackId);const record={...summary,mode:race.mode,questionMode:adaptivePractice?'adaptive':'balanced',id:crypto.randomUUID(),completedAt:new Date().toISOString(),trackId:course.id,world:race.world,car:race.car,stars,topic:race.topic,classLevel:race.classLevel,curriculum:race.curriculum,demo,date:new Date().toLocaleDateString()};rallyProgress.update({...(race.quick?{}:{cup:{[course.id]:stars},progress}),history:[record]});applyAccountProgress();const missed=[...summary.gaps,...summary.unanswered.map(q=>({question_text:q.question_text,question_image_url:q.question_image_url,options:['a','b','c','d'].map(k=>q['option_'+k]),option_images:['a','b','c','d'].map(k=>q['option_'+k+'_image_url']),correct_answer:q.correct_answer,selected:null,topic:q.topic,explanation:q.explanation,unanswered:true}))];shell(`<section class="rally-result">${finishCelebration(summary,stars)}<span class="rally-kicker">${race.quick?'QUICK RACE':'LEVEL '+(courseIndex+1)} · ${esc(course.name)}${race.quick?'':` · ${'★'.repeat(stars)}${'☆'.repeat(3-stars)}`}<br>${summary.finished?'CHEQUERED FLAG':'RACE TIME COMPLETE'}</span><h1>${summary.finished?['','Champion!','Second place!','Third place!','Finish line reached!'][summary.position]:'Keep practising — every lap counts.'}</h1><p class="rally-copy">${esc(race.classLevel)} · ${esc(race.curriculum)} · ${esc(race.topic)}${demo?' · Demo race':''}</p><div class="rally-hud"><article><small>Race position</small><strong>${summary.finished?summary.position+' / 4':'Did not finish'}</strong></article><article><small>Correct answers</small><strong>${summary.correct}/${summary.answered}</strong></article><article><small>Accuracy</small><strong>${summary.accuracy}%</strong></article><article><small>Best streak</small><strong>${summary.bestStreak}</strong></article></div><p class="rally-copy">${Math.round(summary.seconds)} seconds · ${summary.total-summary.answered} unanswered. Practice progress is linked to your account; check the save status above. Official results and rankings are unchanged.</p><div class="rally-actions"><button class="rally-button primary" data-rally-next-course ${allStageAnswersComplete()?'':'disabled'}>${race.quick?'NEXT QUICK RACE':'NEXT COURSE'} · ${esc(RALLY_TRACKS[(courseIndex+1)%RALLY_TRACKS.length].name)} →</button><button class="rally-button" data-rally-retry-stage>${race.quick?'Retry quick race':'Retry this stage'}</button><button class="rally-button" data-rally-again>Change race details</button><button class="rally-button" data-rally-close>Back to platform</button></div><h2>Learning pit stop</h2>${adaptivePractice?'<p class="rally-copy">Adaptive practice used your answers to adjust the next question within this class and topic selection. Difficulty labels reflect the available bank; they are not a mastery grade.</p>':''}<p class="rally-copy">${missed.length?'Revisit these questions, then try similar examples before your next race.':'All questions answered correctly. Try a harder race or another topic.'}</p>${missed.map((a,i)=>`<article class="rally-review"><h3>${i+1}. ${renderVectorText(a.question_text)}</h3>${a.question_image_url?`<img src="${esc(a.question_image_url)}" alt="Question diagram">`:''}<p><b>${a.unanswered?'Unanswered':'Your answer: '+esc(a.selected||'—')+' · '+renderVectorText(a.options?.['ABCD'.indexOf(a.selected)]||'')}</b><br>Correct answer: <b>${esc(a.correct_answer)} · ${renderVectorText(a.options?.['ABCD'.indexOf(a.correct_answer)]||'')}</b>${a.option_images?.['ABCD'.indexOf(a.correct_answer)]?`<br><img src="${esc(a.option_images['ABCD'.indexOf(a.correct_answer)])}" alt="Correct option diagram">`:''}</p><p>${renderVectorText(a.explanation||'Revisit this question with your teacher.')}</p><small>Topic: ${esc(a.topic)}</small></article>`).join('')}</section>`);overlay.scrollTop=0}
function install(){document.querySelectorAll('.screen-tabs .tab-scroll').forEach(menu=>{if(!menu.querySelector('[data-rally-open]'))menu.insertAdjacentHTML('beforeend','<button type="button" class="screen-tab" data-rally-open>🏎️ Maths Rally</button>')});const grid=document.querySelector('.home-screen .home-mode-grid');if(grid&&!grid.querySelector('[data-rally-open]'))grid.insertAdjacentHTML('beforeend','<button type="button" class="home-mode-card game-mode-card rally-home-card" data-rally-open><div class="mode-top"><span class="mode-icon">🏎️</span><em>NEW · PLAYABLE RACING</em></div><h3>Mezzo Maths Rally</h3><p>Power your car with correct answers. Charge turbo. Race three computer drivers to the finish.</p><div class="reward-pill">⚡ Maths Games</div><strong>RACE TO THE FINISH →</strong></button>')}
let installing=false;function queueInstall(){if(installing)return;installing=true;requestAnimationFrame(()=>{installing=false;install()})}
document.addEventListener('click',event=>{if(event.target.closest('[data-rally-open]')){event.preventDefault();event.stopImmediatePropagation();openGame();return}if(!event.target.closest('.rally-overlay'))return;if(event.target.closest('[data-rally-sync]')){syncAccount();return}if(event.target.closest('[data-rally-import-legacy]')){importLegacyProgress();return}if(event.target.closest('[data-rally-close]')){if(classRace){if(window.confirm('End this class race and submit your answers? Remaining questions will be recorded as unanswered.'))finishAssignedRace();return}if(race&&!race.finished&&!window.confirm('Leave this race? This race will not be saved.'))return;closeGame()}if(event.target.closest('[data-rally-camera]')){chaseCamera=!chaseCamera;event.target.closest('button').textContent=chaseCamera?'Camera: chase · switch to stadium':'Camera: stadium · switch to chase'}if(event.target.closest('[data-rally-2d-fallback]'))startRace(demo,{...lastConfig,race_view:'2d',rally_course:race.stageTrackId});if(event.target.closest('[data-rally-sign-in]')){closeGame();document.querySelector('[data-target="auth"]')?.click();return}if(event.target.closest('[data-rally-reload-bank]'))loadQuestions();if(event.target.closest('[data-rally-again]'))showSetup();if(event.target.closest('[data-rally-retry-stage]'))startRace(false,{...lastConfig,rally_course:race.stageTrackId});if(event.target.closest('[data-rally-next-course]')){if(!allStageAnswersComplete())return;selectedTrackId=RALLY_TRACKS[(RALLY_TRACKS.findIndex(track=>track.id===race.stageTrackId)+1)%RALLY_TRACKS.length].id;startRace(demo,{...lastConfig,rally_course:selectedTrackId,race_view:'2d'})}const worldChoice=event.target.closest('[data-rally-world]')?.dataset.rallyWorld;if(worldChoice)chooseGarage('world',worldChoice);const carChoice=event.target.closest('[data-rally-car]')?.dataset.rallyCar;if(carChoice)chooseGarage('car',carChoice);const colourChoice=event.target.closest('[data-rally-colour]')?.dataset.rallyColour;if(colourChoice)chooseGarage('colour',colourChoice);const chosenCourse=event.target.closest('[data-rally-course]')?.dataset.rallyCourse;if(chosenCourse)selectCourse(chosenCourse);const selected=event.target.closest('[data-rally-answer]')?.dataset.rallyAnswer;if(selected)chooseAnswer(selected);if(event.target.closest('[data-rally-pause]')||event.target.closest('[data-rally-resume]'))togglePause();if(event.target.closest('[data-rally-turbo]')&&!paused&&stage==='race')useTurbo(race);if(event.target.closest('[data-rally-sound]')){sound=!sound;event.target.closest('button').textContent=sound?'Sound on':'Sound off';event.target.closest('button').setAttribute('aria-pressed',String(sound));beep()}},true)
document.addEventListener('submit',event=>{if(event.target.matches('[data-rally-setup]')){event.preventDefault();event.stopImmediatePropagation();startRace(false)}},true)
document.addEventListener('change',event=>{if(!event.target.closest('[data-rally-setup]'))return;if(['class_level','curriculum'].includes(event.target.name))loadQuestions();if(event.target.name==='topic')loadTopicQuestions();if(event.target.name==='rally_course'){selectCourse(event.target.value);updateAvailability()}if(event.target.name==='race_view')updateAvailability();if(event.target.name==='race_mode'){if(!canPlayStage(selectedTrackId,currentConfig())){selectedTrackId='sprint';const select=overlay.querySelector('[name="rally_course"]');select.value='sprint'}const cards=overlay.querySelector('.rally-course-picker');if(cards)cards.outerHTML=courseCards();syncQuestionMode();updateAvailability();drawTrack(0)}})
document.addEventListener('visibilitychange',()=>{if(document.hidden&&race&&!race.finished)togglePause(true)})
document.addEventListener('keydown',event=>{if(!overlay)return;if(event.key==='Tab'){const nodes=[...overlay.querySelectorAll('button:not(:disabled),select,a[href]')].filter(n=>n.getClientRects().length);if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}return}if(event.target.matches('input,select,textarea'))return;if(event.key==='Escape'&&race&&!race.finished){event.preventDefault();togglePause();return}if(stage==='race'&&!paused&&!event.repeat){if(/^[1-4]$/.test(event.key)){event.preventDefault();chooseAnswer('ABCD'[Number(event.key)-1])}if(event.code==='Space'){event.preventDefault();useTurbo(race)}}},true)
new MutationObserver(queueInstall).observe(document.body,{childList:true,subtree:true});queueInstall()

// Switch accounts immediately; delayed responses from the old account are discarded by the store.
supabase?.auth.onAuthStateChange((_event,session)=>{const id=session?.user?.id||null;if(id!==rallyProgress.getOwner()){rallyProgress.setOwner(id);if(overlay&&!classRace)closeGame()}})
window.addEventListener('online',()=>{void rallyProgress.sync()})
