export async function openAssignedRally(assigned){
 validateRallyQuestions(assigned.questions)
 if(!assigned.assignment?.rally||!RALLY_TRACKS.some(t=>t.id===assigned.assignment.rally.track)||!Number.isFinite(assigned.deadline))throw Error('This class race has invalid settings.')
 await openGame(assigned)
}
function finishAssignedRace(){
 if(!classRace||classRace.finishing)return
 classRace.finishing=true
 const current=classRace,summary=summariseRace(race,questions)
 cancelAnimationFrame(raf);closeGame()
 void current.onFinish(summary)
}

function syncQuestionMode(){const form=overlay?.querySelector('[data-rally-setup]');if(form?.elements.question_mode)form.elements.question_mode.disabled=!quickRace(currentConfig())}
